From d24931ff82eff59bcb5529b366f320bbbbccfe83 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 19:40:46 +0100
Subject: [PATCH] components: let the battery icon turn red at a given charge
 level

The low battery icons are red in the icon theme, so the battery icon
turned red below 15% regardless of when the battery is considered low.
Add an optional low level to the battery icon and expose powerdevil's.

BUG: 492798
---
 components/batterycontrol/batterycontrol.cpp | 41 ++++++++++++++++++++
 components/batterycontrol/batterycontrol.h   |  5 +++
 components/workspace/BatteryIcon.qml         |  7 +++-
 3 files changed, 52 insertions(+), 1 deletion(-)

diff --git a/components/batterycontrol/batterycontrol.cpp b/components/batterycontrol/batterycontrol.cpp
index 060d5895ac..90b8f80520 100644
--- a/components/batterycontrol/batterycontrol.cpp
+++ b/components/batterycontrol/batterycontrol.cpp
@@ -156,6 +156,22 @@ void BatteryControlModel::onServiceRegistered(const QString &serviceName)
             watcher->deleteLater();
         });

+        QDBusMessage batteryLowLevelMessage = QDBusMessage::createMethodCall(SOLID_POWERMANAGEMENT_SERVICE,
+                                                                             SOLID_POWERMANAGEMENT_PATH,
+                                                                             SOLID_POWERMANAGEMENT_IFACE,
+                                                                             QStringLiteral("batteryLowLevel"));
+        QDBusPendingCall batteryLowLevelCall = QDBusConnection::sessionBus().asyncCall(batteryLowLevelMessage);
+        auto batteryLowLevelWatcher = new QDBusPendingCallWatcher(batteryLowLevelCall, this);
+        connect(batteryLowLevelWatcher, &QDBusPendingCallWatcher::finished, this, [this](QDBusPendingCallWatcher *watcher) {
+            QDBusReply<int> reply = *watcher;
+            if (reply.isValid()) {
+                m_batteryLowLevel = reply.value();
+            } else {
+                qCDebug(COMPONENTS::BATTERYCONTROL) << "error getting battery low level";
+            }
+            watcher->deleteLater();
+        });
+
         if (!QDBusConnection::sessionBus().connect(SOLID_POWERMANAGEMENT_SERVICE,
                                                    SOLID_POWERMANAGEMENT_PATH,
                                                    SOLID_POWERMANAGEMENT_IFACE,
@@ -183,6 +199,15 @@ void BatteryControlModel::onServiceRegistered(const QString &serviceName)
             qCDebug(COMPONENTS::BATTERYCONTROL) << "error connecting to charge stop threshold changes via dbus";
         }

+        if (!QDBusConnection::sessionBus().connect(SOLID_POWERMANAGEMENT_SERVICE,
+                                                   SOLID_POWERMANAGEMENT_PATH,
+                                                   SOLID_POWERMANAGEMENT_IFACE,
+                                                   QStringLiteral("batteryLowLevelChanged"),
+                                                   this,
+                                                   SLOT(updateBatteryLowLevel(int)))) {
+            qCDebug(COMPONENTS::BATTERYCONTROL) << "error connecting to battery low level changes via dbus";
+        }
+
         QDBusMessage PowerSaveStatusMessage = QDBusMessage::createMethodCall(QStringLiteral("org.freedesktop.PowerManagement"),
                                                                              QStringLiteral("/org/freedesktop/PowerManagement"),
                                                                              QStringLiteral("org.freedesktop.PowerManagement"),
@@ -231,6 +256,12 @@ void BatteryControlModel::onServiceUnregistered(const QString &serviceName)
                                                  QStringLiteral("chargeStopThresholdChanged"),
                                                  this,
                                                  SLOT(updateBatteryChargeStopThreshold(int)));
+        QDBusConnection::sessionBus().disconnect(SOLID_POWERMANAGEMENT_SERVICE,
+                                                 SOLID_POWERMANAGEMENT_PATH,
+                                                 SOLID_POWERMANAGEMENT_IFACE,
+                                                 QStringLiteral("batteryLowLevelChanged"),
+                                                 this,
+                                                 SLOT(updateBatteryLowLevel(int)));
         QDBusConnection::sessionBus().disconnect(QStringLiteral("org.freedesktop.PowerManagement"),
                                                  QStringLiteral("/org/freedesktop/PowerManagement"),
                                                  QStringLiteral("org.freedesktop.PowerManagement"),
@@ -527,6 +558,11 @@ void BatteryControlModel::updateBatteryChargeStopThreshold(int threshold)
     m_chargeStopThreshold = threshold;
 }

+void BatteryControlModel::updateBatteryLowLevel(int level)
+{
+    m_batteryLowLevel = level;
+}
+
 void BatteryControlModel::updateAcPlugState(bool onBattery)
 {
     m_pluggedIn = !onBattery;
@@ -646,6 +682,11 @@ QBindable<int> BatteryControlModel::bindableChargeStopThresholdChanged()
     return &m_chargeStopThreshold;
 }

+QBindable<int> BatteryControlModel::bindableBatteryLowLevel()
+{
+    return &m_batteryLowLevel;
+}
+
 QBindable<qulonglong> BatteryControlModel::bindableRemainingMsec()
 {
     return &m_remainingMsec;
diff --git a/components/batterycontrol/batterycontrol.h b/components/batterycontrol/batterycontrol.h
index c847bd424f..45eecca3d4 100644
--- a/components/batterycontrol/batterycontrol.h
+++ b/components/batterycontrol/batterycontrol.h
@@ -32,6 +32,7 @@ class BatteryControlModel : public QAbstractListModel
     Q_PROPERTY(bool hasInternalBatteries READ default NOTIFY hasInternalBatteriesChanged BINDABLE bindableHasInternalBatteries)
     Q_PROPERTY(ChargeStateEnum state READ default NOTIFY stateChanged BINDABLE bindableState)
     Q_PROPERTY(int chargeStopThreshold READ default NOTIFY chargeStopThresholdChanged BINDABLE bindableChargeStopThresholdChanged)
+    Q_PROPERTY(int batteryLowLevel READ default NOTIFY batteryLowLevelChanged BINDABLE bindableBatteryLowLevel)
     Q_PROPERTY(qulonglong remainingMsec READ default NOTIFY remainingMsecChanged BINDABLE bindableRemainingMsec)
     Q_PROPERTY(qulonglong smoothedRemainingMsec READ default NOTIFY smoothedRemainingMsecChanged BINDABLE bindableSmoothedRemainingMsec)
     Q_PROPERTY(int percent READ default NOTIFY percentChanged BINDABLE bindablePercent)
@@ -71,6 +72,7 @@ private:
     QBindable<bool> bindableHasInternalBatteries();
     QBindable<ChargeStateEnum> bindableState();
     QBindable<int> bindableChargeStopThresholdChanged();
+    QBindable<int> bindableBatteryLowLevel();
     QBindable<qulonglong> bindableRemainingMsec();
     QBindable<qulonglong> bindableSmoothedRemainingMsec();
     QBindable<int> bindablePercent();
@@ -94,6 +96,7 @@ private Q_SLOTS:
     void batteryRemainingTimeChanged(qulonglong time);
     void smoothedBatteryRemainingTimeChanged(qulonglong time);
     void updateBatteryChargeStopThreshold(int threshold);
+    void updateBatteryLowLevel(int level);
     void updateAcPlugState(bool onBattery);
     void updateOverallBattery();

@@ -107,6 +110,7 @@ Q_SIGNALS:
     void hasInternalBatteriesChanged(bool status);
     void stateChanged(ChargeStateEnum state);
     void chargeStopThresholdChanged(int threshold);
+    void batteryLowLevelChanged(int level);
     void remainingMsecChanged(qulonglong time);
     void smoothedRemainingMsecChanged(qulonglong time);
     void percentChanged(int percent);
@@ -118,6 +122,7 @@ private:
     Q_OBJECT_BINDABLE_PROPERTY_WITH_ARGS(BatteryControlModel, bool, m_pluggedIn, false, &BatteryControlModel::pluggedInChanged)
     Q_OBJECT_BINDABLE_PROPERTY(BatteryControlModel, ChargeStateEnum, m_state, &BatteryControlModel::stateChanged)
     Q_OBJECT_BINDABLE_PROPERTY_WITH_ARGS(BatteryControlModel, int, m_chargeStopThreshold, 0, &BatteryControlModel::chargeStopThresholdChanged)
+    Q_OBJECT_BINDABLE_PROPERTY_WITH_ARGS(BatteryControlModel, int, m_batteryLowLevel, -1, &BatteryControlModel::batteryLowLevelChanged)
     Q_OBJECT_BINDABLE_PROPERTY_WITH_ARGS(BatteryControlModel, qulonglong, m_remainingMsec, 0, &BatteryControlModel::remainingMsecChanged)
     Q_OBJECT_BINDABLE_PROPERTY_WITH_ARGS(BatteryControlModel, qulonglong, m_smoothedRemainingMsec, 0, &BatteryControlModel::smoothedRemainingMsecChanged)
     Q_OBJECT_BINDABLE_PROPERTY_WITH_ARGS(BatteryControlModel, int, m_percent, 0, &BatteryControlModel::percentChanged)
diff --git a/components/workspace/BatteryIcon.qml b/components/workspace/BatteryIcon.qml
index 42271bef6e..094a17db23 100644
--- a/components/workspace/BatteryIcon.qml
+++ b/components/workspace/BatteryIcon.qml
@@ -20,6 +20,9 @@ Item {
     property bool active: false
     property string powerProfileIconName: ""
     property bool preferSymbolic: false
+    // Charge level at or below which the battery is shown as low, or -1 to
+    // use the icon theme's own low battery icons
+    property int lowPercent: -1

     // Icon for current charge level, charging status, and optionally power
     // profile indication (for batteries that support it by setting
@@ -29,6 +32,7 @@ Item {
         source: (root.hasBattery ? fillElement(root.percent) : "battery-missing") + (root.preferSymbolic ? "-symbolic" : "")
         visible: !otherBatteriesIcon.visible
         active: root.active
+        color: root.hasBattery && root.percent <= root.lowPercent ? Kirigami.Theme.negativeTextColor : "transparent"

         function fillElement(p: int): string {
             // Don't show the battery icon when fully charged and plugged in;
@@ -54,7 +58,8 @@ Item {
                 name = "battery-040";
             } else if (p >= 25) {
                 name = "battery-030";
-            } else if (p >= 15) {
+            } else if (p >= 15 || (root.lowPercent >= 0 && p > root.lowPercent)) {
+                // Lower level icons are red, so only use them when the battery is low
                 name = "battery-020";
             } else if (p > 5) {
                 name = "battery-010";
-- 
